sys_script_include.script:
var CreateCarWashEntitlement = Class.create();
CreateCarWashEntitlement.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    createEntitlement: function() {
        var plan = this.getParameter('sysparm_plan');
        var consumerUserSysId = this.getParameter('sysparm_consumer');
        var entName = "Water service – " + plan + " Plan";
        var maxUnits = (plan == "Advance") ? 10 : (plan == "Premium") ? 5 : 0;

        var ent = new GlideRecord("service_entitlement");
        ent.initialize();
        ent.entitlement_name = entName;
        ent.total_units = maxUnits;
		ent.remaining_units=maxUnits;

        var start = new GlideDateTime();
        var end = new GlideDateTime();
        end.addYearsLocalTime(1);

        ent.start_date = start;
        ent.end_date = end;
        ent.business_hour = "08fcd0830a0a0b2600079f56b1adb9ae"; // Example
       var gr=new GlideRecord("csm_consumer_user");
		gr.addQuery("user_name",consumerUserSysId);
		gr.query();
		if(gr.next())
		{

			var g=new GlideRecord("csm_consumer");
			g.addQuery("name",gr.name);
			g.query();
			if(g.next())
			{

				ent.consumer=g.sys_id;
			}
		}

        ent.insert();

        return "created";
    }

});
